PARAM_SPECS = {
    "tight_space_distance_m": (1.0, 6.0, 3.0),
    "direct_approach_angle_deg": (15.0, 60.0, 35.0),
    "high_closing_speed_mps": (0.5, 3.0, 1.5),
    "escape_space_distance_m": (3.0, 10.0, 6.0),
    "support_min_count": (0.0, 3.0, 1.0),
    "sideline_danger_distance_m": (1.0, 8.0, 4.0),
    "attacking_third_distance_m": (15.0, 40.0, 25.0),
}

def predict_take_on(f: dict, p: dict) -> int:
    is_tight_space = f["distance_m"] < p["tight_space_distance_m"]

    is_direct_threat = (
        f["approach_angle_deg"] < p["direct_approach_angle_deg"]
        and f["closing_speed_mps"] > p["high_closing_speed_mps"]
    )

    has_escape_space = f["second_nearest_dist_m"] > p["escape_space_distance_m"]

    has_backup_support = f["n_supporting_teammates"] >= p["support_min_count"]

    is_pinned_to_sideline = f["dist_to_sideline_m"] < p["sideline_danger_distance_m"]

    is_dangerous_zone = f["dist_to_goal_line_m"] < p["attacking_third_distance_m"]

    carrier_has_speed_edge = f["carrier_speed_mps"] >= f["opponent_speed_mps"]

    if is_tight_space and is_direct_threat:
        if is_pinned_to_sideline and not has_escape_space:
            take_on = False
        else:
            take_on = has_escape_space and (has_backup_support or is_dangerous_zone)
    elif is_tight_space and not is_direct_threat:
        take_on = has_escape_space and carrier_has_speed_edge and (has_backup_support or is_dangerous_zone)
    else:
        take_on = False

    return 1 if take_on else 0
